G=load(); print(sorted(G))
# New idea: recolor cells that are "shadowed"/visible between TWO seeds such that the cell lies strictly BETWEEN them along a manhattan path? Or simpler: recolored = bg cells where the number of seeds on one side (i.e., seeds with i+j < i'+j'?) ... Try: recolored iff (i-j) has same sign relationship... 
# Let's just directly compute: recolored set vs anti-diag index histogram per residue class mod p for both demos jointly — find p and residue pattern consistent across BOTH demos!
for n,bgc,sev in [(7,6,1),(8,4,2)]:
    I=np.array(G[f'Demo pair {n} input']); O=np.array(G[f'Demo pair {n} output'])
    rec=(O==5)&(I!=sev); R,C_=rec.shape
    S=list(map(tuple,np.argwhere(I==sev)))
    # For each bg cell compute features; check separability by pairs like ((i+j)%p,(i-j)%q) with p,q up to 6
    best=None
    for p in range(1,7):
        for q in range(1,7):
            tab=defaultdict(Counter)
            for i in range(R):
                for j in range(C_):
                    if I[i][j]==bgc:
                        tab[((i+j)%p,(i-j)%q)][int(rec[i][j])]+=1
            # accuracy of majority vote per bucket
            ok=sum(max(v.values()) if max(v.values())>sum(v.values())-max(v.values()) else 0 for v in tab.values())/len(tab)
            frac=sum(v.get(1,0)/sum(v.values()) for v in tab.values())/len(tab)
            if best is None or frac>best[0]: best=(frac,p,q,{k:v for k,v in tab.items()})
    print('demo',n,'best:',round(best[0],3),best[1],best[2])
